import { Duplex } from 'readable-stream';
import { isValidMethod, isJRPCNotification } from '../utils/jrpc.js';
import { SafeEventEmitter } from './safeEventEmitter.js';
import { SerializableError } from './serializableError.js';
import { errorCodes } from './errors/error-constants.js';

/**
 * @deprecated Part of the JRPC V1 API. Use {@link JRPCEngineV2} which returns
 * results directly from `handle()` without requiring callbacks.
 */
const getRpcPromiseCallback = (resolve, reject, unwrapResult = true) => (error, response) => {
  if (error || response.error) {
    reject(error || response.error);
  } else if (!unwrapResult || Array.isArray(response)) {
    resolve(response);
  } else {
    resolve(response.result);
  }
};

/**
 * @deprecated Part of the JRPC V1 API. The V2 engine handles errors internally
 * via {@link JRPCEngineV2}.
 */
function createErrorMiddleware(log) {
  return (req, res, next, end) => {
    try {
      // json-rpc-engine will terminate the request when it notices this error
      if (!isValidMethod(req)) {
        res.error = new SerializableError({
          code: errorCodes.rpc.invalidRequest,
          message: "invalid method"
        });
        end();
        return;
      }
      next(done => {
        const {
          error
        } = res;
        if (!error) {
          return done();
        }
        log.error(`Auth - RPC Error: ${error.message}`, error);
        return done();
      });
    } catch (error) {
      log.error(`Auth - RPC Error thrown: ${error.message}`, error);
      res.error = new SerializableError({
        code: errorCodes.rpc.internal,
        message: error.message
      });
      end();
    }
  };
}

